{
    "name": "@liustack/modlens",
    "version": "3.18.3",
    "description": "Plug-in vision for text-only LLMs, powered by the free Antigravity CLI",
    "type": "module",
    "bin": {
        "modlens": "./dist/main.js"
    },
    "scripts": {
        "dev": "vite build --watch",
        "build": "vite build",
        "typecheck": "tsc --noEmit",
        "test": "vitest run",
        "coverage": "vitest run --coverage",
        "lint": "biome check src scripts dsh",
        "format": "biome check --write src scripts",
        "eval": "node evals/run.mjs",
        "release": "node scripts/release.mjs",
        "prepublishOnly": "pnpm build",
        "docs:list": "node scripts/docs-list.js"
    },
    "files": [
        "dist",
        "docs",
        "skills/modlens/SKILL.md",
        "skills/modlens/scripts",
        "skills/modlens/references",
        "CHANGELOG.md",
        "SECURITY.md",
        "dsh",
        "cordis.patch.yml"
    ],
    "keywords": [
        "cli",
        "vision",
        "ocr",
        "antigravity",
        "agent-skill",
        "claude-code",
        "skill",
        "image-to-text",
        "multimodal",
        "modlens"
    ],
    "author": "Leon Liu",
    "license": "MIT",
    "repository": {
        "type": "git",
        "url": "git+https://github.com/liustack/modlens.git"
    },
    "bugs": {
        "url": "https://github.com/liustack/modlens/issues"
    },
    "homepage": "https://github.com/liustack/modlens#readme",
    "engines": {
        "node": ">=22.19"
    },
    "dependencies": {
        "commander": "^13.1.0",
        "undici": "^8.10.0"
    },
    "devDependencies": {
        "@biomejs/biome": "^2.5.7",
        "@types/node": "^22.19.7",
        "@vitest/coverage-v8": "^3.2.7",
        "typescript": "^5.9.3",
        "vite": "^6.4.1",
        "vitest": "^3.2.7"
    },
    "exports": {
        ".": "./dsh/index.js",
        "./dsh": "./dsh/index.js",
        "./package.json": "./package.json",
        "./client": "./dsh/client.js"
    },
    "dsh": {
        "bundle": {
            "patch": "./cordis.patch.yml"
        },
        "client": {
            "inject": [],
            "platform": "web",
            "immediately": true
        }
    }
}

{
  "name": "life-level-up-guide",
  "version": "1.0.0",
  "private": true,
  "description": "人生进阶指南：英语学习、AI 学习与长期成长的开放内容项目",
  "type": "module",
  "engines": {
    "node": ">=24 <25"
  },
  "scripts": {
    "docs:dev": "vitepress dev docs",
    "docs:build": "vitepress build docs",
    "docs:preview": "vitepress preview docs",
    "check:content": "node scripts/check-content.mjs",
    "check:navigation": "node scripts/sync-navigation.mjs --check && node scripts/sync-word-lists.mjs --check && node scripts/sync-public-assets.mjs --check",
    "check:readme": "node scripts/sync-readme.mjs --check",
    "check:format": "markdownlint-cli2 \"**/*.md\" \"#node_modules\" \"#docs/.vitepress/dist\"",
    "check": "npm run check:navigation && npm run check:readme && npm run check:content && npm run check:format",
    "sync": "node scripts/sync-navigation.mjs && node scripts/sync-word-lists.mjs && node scripts/sync-public-assets.mjs && node scripts/sync-readme.mjs",
    "test:smoke": "playwright test",
    "assets:sanitize": "node scripts/sanitize-assets.mjs"
  },
  "devDependencies": {
    "@playwright/test": "1.62.1",
    "markdownlint-cli2": "0.23.2",
    "sharp": "0.35.3",
    "vitepress": "1.6.4"
  },
  "overrides": {
    "esbuild": "0.25.12",
    "vite": "6.4.3"
  }
}

{
  "name": "immich-monorepo",
  "version": "3.1.0",
  "description": "Monorepo for Immich",
  "type": "module",
  "private": true,
  "scripts": {
    "format": "prettier --cache --check i18n/",
    "format:fix": "prettier --cache --write --list-different i18n"
  },
  "packageManager": "pnpm@11.20.0",
  "engines": {
    "pnpm": ">=10.0.0"
  },
  "devDependencies": {
    "prettier": "^3.8.3",
    "prettier-plugin-sort-json": "^4.2.0"
  }
}

