nautilus-indicators = { path = "crates/indicators", version = "0.62.0" }
nautilus-infrastructure = { path = "crates/infrastructure", version = "0.62.0" }
nautilus-live = { path = "crates/live", version = "0.62.0", default-features = false }
nautilus-model = { path = "crates/model", version = "0.62.0" }
nautilus-network = { path = "crates/network", version = "0.62.0" }
nautilus-persistence = { path = "crates/persistence", version = "0.62.0" }
nautilus-persistence-macros = { path = "crates/persistence/macros", version = "0.62.0" }
nautilus-portfolio = { path = "crates/portfolio", version = "0.62.0" }
